import{_ as a,o as n,c as t,a5 as i}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Cabochon & Carving","description":"","frontmatter":{"title":"Cabochon & Carving","cutting":"cabochon-and-carving"},"headers":[],"relativePath":"cutting/cabochon-and-carving.md","filePath":"cutting/cabochon-and-carving.md","lastUpdated":1790876393000}'),o={name:"cutting/cabochon-and-carving.md"};function r(s,e,c,l,d,h){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="cabochon-carving" tabindex="-1">Cabochon &amp; Carving <a class="header-anchor" href="#cabochon-carving" aria-label="Permalink to &quot;Cabochon &amp; Carving&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>When transparency, inclusions, durability, or an optical phenomenon favors a dome, a stone may be polished en cabochon or carved. This is not an absolute ban on faceting. Cabochons can reveal asterism, chatoyancy, and adularescence; jade and agate are also often carved.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-cabochon-and-carving-en"><p class="gem-identification-boundary__eyebrow">CUTTING BOUNDARY</p><h2 id="identification-boundary-cabochon-and-carving-en">Boundary &amp; Safety</h2><p>This page explains relationships among cabochons, carving, and optical phenomena; it does not replace specimen checks of dome height, curvature, inclusion orientation, fractures, or polish. A specialist should review unusual phenomena and durability. </p></aside><h2 id="case-flow" tabindex="-1">Case Flow <a class="header-anchor" href="#case-flow" aria-label="Permalink to &quot;Case Flow&quot;">​</a></h2><blockquote><p>Teaching case (demonstration): this records the reasoning for a cabochon route; it does not replace physical orientation or cutting.</p></blockquote><h3 id="_1-confirm-why-a-dome-is-being-chosen" tabindex="-1">1. Confirm why a dome is being chosen <a class="header-anchor" href="#_1-confirm-why-a-dome-is-being-chosen" aria-label="Permalink to &quot;1. Confirm why a dome is being chosen&quot;">​</a></h3><p>State whether transparency, inclusions, durability, or asterism/chatoyancy drives the cabochon route. “It is easier to cut” is not enough on its own.</p><h3 id="_2-find-the-phenomenon-direction" tabindex="-1">2. Find the phenomenon direction <a class="header-anchor" href="#_2-find-the-phenomenon-direction" aria-label="Permalink to &quot;2. Find the phenomenon direction&quot;">​</a></h3><p>Under different directions and lights, record the direction, continuity, and strength of needles or bands. Mark the area the dome should align with; do not make a definitive promise when orientation is uncertain.</p><h3 id="_3-compare-dome-plans" tabindex="-1">3. Compare dome plans <a class="header-anchor" href="#_3-compare-dome-plans" aria-label="Permalink to &quot;3. Compare dome plans&quot;">​</a></h3><p>Compare single/double cabochon, dome height, curvature continuity, and base stability. Record band width, brightness, evenness, and weak areas, then review under consistent light.</p><h3 id="_4-stop-conditions" tabindex="-1">4. Stop conditions <a class="header-anchor" href="#_4-stop-conditions" aria-label="Permalink to &quot;4. Stop conditions&quot;">​</a></h3><p>If inclusion direction, fractures, dome continuity, or polish cannot be confirmed, stop naming the specimen “star” or “cat&#39;s-eye”. Record it as a candidate phenomenon and seek specialist review.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Single / double cabochon: height controls star and cat&#39;s-eye definition.</li><li>Asterism requires oriented polishing — rutile needles parallel to the table.</li><li>Chatoyancy likewise: needle inclusions must align to the dome axis.</li><li>Jade carving (jadeite, nephrite, turquoise) exploits texture and colour zoning.</li><li>Dome height, curvature, and polish together affect the width, brightness, and evenness of the band.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Cut</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>Star cabochon</td><td>6-ray asterism</td></tr><tr><td>tigers-eye</td><td>Cat&#39;s-eye cabochon</td><td>Chatoyancy</td></tr><tr><td>jadeite</td><td>Carved pendant</td><td>Carved pendant</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gia-news-research-value-factors-gem-cutting-styles-definitions" target="_blank" rel="noreferrer">GIA: Gem Cutting Styles — Definitions</a><span>Definitions of outlines, facet arrangements, step cuts, cabochons, and carving styles</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors and Cut Quality</a><span>Cut trade-offs among proportions, symmetry, polish, rough limitations, and appearance</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-cut/" target="_blank" rel="noreferrer">GIA: Diamond Cut</a><span>Round-brilliant table, crown, girdle, pavilion, and the 57/58-facet count</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>How colored-stone cutting weighs color, durability, inclusions, and fractures</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-cabochon-and-carving-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-cabochon-and-carving-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Cabochon and carving are common finished-form routes whose suitability depends on the material and design goal.</span><small>GIA: Gem Cutting Styles — Definitions; GIA: Colored Gemstone Value Factors and Cut Quality</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>Presenting phenomena such as asterism and chatoyancy requires considering inclusion orientation, dome geometry, and polish together.</span><small>GIA: Colored Gemstone Value Factors and Cut Quality; GIA: Gem Cutting Styles — Definitions</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>The teaching case connects phenomenon orientation, dome design, and stop conditions into a reviewable record.</span><small>GIA: Gem Cutting Styles — Definitions; GIA: Colored Gemstone Value Factors and Cut Quality</small></li></ul></aside><p><em>See the <a href="./intro.html">cutting overview</a>.</em></p>',21)])])}const p=a(o,[["render",r]]);export{m as __pageData,p as default};
